import {
  formatBp,
  groupDigits
} from "./chunk-G2XUZB3Y.js";
import {
  NOT_LOADED_TEXT
} from "./chunk-LTXIMO7C.js";
import {
  panSNHaplotype
} from "./chunk-W6DDM47C.js";

// src/hoverText.ts
function regionLabel(loc) {
  return `${loc.refName}:${groupDigits(loc.start + 1)}-${groupDigits(loc.end)}`;
}
function edgeHoverText(edge, deletion, nameOf = (id) => id) {
  return deletion ? {
    deletion: {
      bp: `${groupDigits(deletion.bp)} bp`,
      where: regionLabel(deletion)
    }
  } : {
    ends: `${nameOf(edge.from)}${edge.fromStrand ?? ""} \u2192 ${nameOf(edge.to)}${edge.toStrand ?? ""}`
  };
}
function placeholderHoverText(node) {
  const walk = node.stable?.refName ?? node.name;
  return node.placeholder ? `${formatBp(node.length)} of ${panSNHaplotype(walk) ?? walk}'s route, ${NOT_LOADED_TEXT}` : void 0;
}

export {
  regionLabel,
  edgeHoverText,
  placeholderHoverText
};
