import {
  LABEL_PAD,
  LABEL_PX,
  labelWidth
} from "./chunk-DV4M2KL4.js";

// src/passLabels.ts
var ABOVE_PX = 8;
var gap = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
var median = (values) => values.toSorted((a, b) => a - b)[values.length >> 1] ?? 0;
function passLabelCandidates(batch, lift, t, pane) {
  const spots = batch.nodeStrokes.flatMap((stroke) => {
    const middle = stroke.points[stroke.points.length >> 1];
    const at = middle && {
      x: middle.x * t.scaleX + t.translateX,
      y: middle.y * t.scaleY + t.translateY
    };
    return at && stroke.walk !== void 0 && (stroke.walkPass ?? -1) >= 0 && at.x >= 0 && at.x <= pane.width && at.y >= 0 && at.y <= pane.height ? [{ walk: stroke.walk, pass: stroke.walkPass ?? -1, at }] : [];
  });
  const centre = {
    x: median(spots.map((s) => s.at.x)),
    y: median(spots.map((s) => s.at.y))
  };
  const taken = [];
  const furthest = (from) => {
    let best;
    let reach = -1;
    for (const spot of from) {
      const d = taken.length === 0 ? gap(spot.at, centre) : taken.reduce(
        (least, p) => Math.min(least, gap(spot.at, p)),
        Infinity
      );
      if (d > reach) {
        reach = d;
        best = spot;
      }
    }
    return best;
  };
  const candidates = [];
  for (const [lane, walk] of (lift?.walks ?? []).entries()) {
    const drawn = walk.walkPasses;
    const own = spots.filter((s) => s.walk === lane);
    const named = !drawn ? [] : drawn.bundled ? drawn.passes.slice(0, 1).map(({ label, ink }) => ({
      pass: -1,
      text: label,
      ink,
      from: own
    })) : drawn.passes.map(({ label, ink }, pass) => ({
      pass,
      text: label,
      ink,
      from: own.filter((s) => s.pass === pass)
    }));
    for (const { pass, text, ink, from } of named) {
      const spot = furthest(from);
      if (spot) {
        taken.push(spot.at);
        const { x, y } = spot.at;
        candidates.push({
          item: {
            walk: walk.name,
            pass,
            ink,
            at: spot.at
          },
          x,
          y: y - ABOVE_PX,
          flipY: y + ABOVE_PX + LABEL_PX,
          text,
          stack: 2,
          slide: labelWidth(text),
          nearest: spot.at
        });
      }
    }
  }
  return candidates;
}
function passLeader(label, at) {
  return {
    x1: label.x,
    y1: label.y > at.y ? label.y - LABEL_PX - LABEL_PAD : label.y + LABEL_PAD,
    x2: at.x,
    y2: at.y
  };
}

export {
  passLabelCandidates,
  passLeader
};
