import {
  formatBp
} from "./chunk-G2XUZB3Y.js";

// src/threadKey.ts
function threadLabel(thread, own, picked = []) {
  const count = thread.count ?? 1;
  return count > 1 ? `${count.toLocaleString("en-US")} haplotypes${picked.length > 0 ? `, ${picked.join(", ")} among them` : ""}` : thread.pieces ? `${own}, one of its ${thread.pieces} pieces here` : own;
}
var threadFoldKey = ({ belowBp }) => `a thread is the haplotypes alike in every difference of ${formatBp(belowBp)} or more; smaller ones are not drawn`;

export {
  threadLabel,
  threadFoldKey
};
