// src/layout/fitAssumptions.ts
var FIGURE_WIDTH_PX = 1200;
var FIT_PADDING = 40;
var TRACK_FLOOR_PX = 280;
var ASSUMED_FIT = {
  width: FIGURE_WIDTH_PX,
  height: TRACK_FLOOR_PX
};
function fitOrAssumed(fit) {
  return fit && fit.width > 2 * FIT_PADDING && fit.height > 2 * FIT_PADDING ? fit : ASSUMED_FIT;
}
function fitRoom(fit) {
  return {
    width: fit.width - 2 * FIT_PADDING,
    height: fit.height - 2 * FIT_PADDING
  };
}

export {
  FIGURE_WIDTH_PX,
  FIT_PADDING,
  TRACK_FLOOR_PX,
  ASSUMED_FIT,
  fitOrAssumed,
  fitRoom
};
