import {
  MIN_WALK_LANE_PX
} from "./chunk-HUZBOWVR.js";
import {
  el,
  elOf
} from "./chunk-HKNMZOFV.js";

// src/genes/exonOutline.ts
var EXON_COLOR = "#daa520";
var EXON_GAP_PX = 1;
var EXON_LINE_PX = 2;
var EXON_RIM_PX = EXON_GAP_PX + EXON_LINE_PX;
function exonStretches(pins, halfWidthPx, lift, pathOf = (d) => d, folded) {
  const inkPx = (nodeId) => {
    const own = halfWidthPx(nodeId) * 2;
    return lift?.nodeIds.has(nodeId) ? Math.max(own, lift.walks.length * MIN_WALK_LANE_PX) : own;
  };
  return pins.flatMap(
    (pin) => pin.exonsByNode.flatMap(
      ({ nodeId, d }) => folded?.has(nodeId) ? [] : [
        {
          key: `${pin.gene.name}-${pin.gene.refName}-${pin.gene.start}-${nodeId}`,
          d: pathOf(d),
          inner: inkPx(nodeId) + 2 * EXON_GAP_PX
        }
      ]
    )
  );
}
function exonOutlineTree(stretches, o) {
  if (stretches.length === 0) {
    return void 0;
  }
  const stroke = (s, color, width) => el("path", {
    d: s.d,
    fill: "none",
    stroke: color,
    "stroke-width": width,
    "stroke-linecap": "round",
    "stroke-linejoin": "round",
    "vector-effect": o.transform ? "non-scaling-stroke" : void 0
  });
  return el(
    "g",
    {},
    el(
      "mask",
      {
        id: o.id,
        maskUnits: "userSpaceOnUse",
        x: 0,
        y: 0,
        width: o.width,
        height: o.height
      },
      elOf(
        "g",
        { transform: o.transform },
        stretches.map((s) => stroke(s, "#fff", s.inner + 2 * EXON_LINE_PX)).concat(stretches.map((s) => stroke(s, "#000", s.inner)))
      )
    ),
    el("rect", {
      width: o.width,
      height: o.height,
      fill: EXON_COLOR,
      mask: `url(#${o.id})`
    })
  );
}

export {
  EXON_COLOR,
  EXON_RIM_PX,
  exonStretches,
  exonOutlineTree
};
